alter table deputy_import_batches add column if not exists segmented_rows integer not null default 0;
create table labour_segments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),import_batch_id uuid not null references deputy_import_batches(id),source_timesheet_row_id uuid not null references deputy_raw_timesheets(id),person_key text not null,area_code text not null,segment_start timestamptz not null,segment_end timestamptz not null,calendar_date date not null,operational_date date not null,hour_bucket smallint not null check(hour_bucket between 0 and 23),shift_code text not null,paid_hours numeric not null,regular_hours numeric not null,overtime_hours numeric not null,paid_break_hours numeric not null,productive_hours numeric not null,approval_status text not null,allocation_method text not null default'PRO_RATA_ELAPSED',week_start date not null,calculation_version text not null default'V29_DAILY8_WEEKLY38_WEEKEND_OT_PAID_BREAK20',created_at timestamptz not null default now(),unique(source_timesheet_row_id,segment_start));create index labour_segments_period_idx on labour_segments(organization_id,operational_date,shift_code,area_code);create index labour_segments_person_week_idx on labour_segments(organization_id,person_key,week_start);alter table labour_segments enable row level security;revoke all on labour_segments from anon,authenticated;grant select,insert,delete on labour_segments to service_role;
